/* Orchard — Premium Tech Store */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root {
  --color-bg: #ffffff;
  --color-bg-alt: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --section-padding: 80px 0;
  --card-radius: 18px;
  --transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body { font-family: var(--font-stack); color: var(--color-text); background: var(--color-bg); line-height: 1.47059; font-size: 17px; overflow-x: hidden; }
a { color: var(--color-link); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-link-hover); text-decoration: underline; }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ─── Ribbon Banner ─── */
.ribbon {
  background: var(--color-bg-alt);
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
}
.ribbon a { font-weight: 500; }

/* ─── Top Navigation ─── */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
}
.top-nav__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 48px;
}
.top-nav__logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
}
.top-nav__logo:hover { text-decoration: none; color: var(--color-text); }
.top-nav__links { display: flex; gap: 28px; align-items: center; }
.top-nav__links a {
  font-size: 14px;
  color: var(--color-text);
  font-weight: 400;
  opacity: 0.8;
  transition: opacity var(--transition);
}
.top-nav__links a:hover { opacity: 1; text-decoration: none; }
.top-nav__links a.active { opacity: 1; font-weight: 600; }

.nav-hamburger { display: none; width: 36px; height: 36px; align-items: center; justify-content: center; }
.nav-hamburger svg { width: 20px; height: 20px; }

/* ─── Mobile Nav ─── */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 999;
}
.mobile-nav-overlay.is-open { display: block; }
.mobile-nav {
  position: fixed;
  top: 0; right: -280px;
  width: 280px; height: 100%;
  background: #fff;
  z-index: 1001;
  padding: 60px 24px 24px;
  transition: right var(--transition);
  box-shadow: -4px 0 20px rgba(0,0,0,0.1);
}
.mobile-nav.is-open { right: 0; }
.mobile-nav a { display: block; padding: 14px 0; font-size: 17px; color: var(--color-text); border-bottom: 1px solid var(--color-border); }
.mobile-nav__close {
  position: absolute; top: 16px; right: 16px;
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; color: var(--color-text-secondary);
}

/* ─── Section Containers ─── */
.section { padding: var(--section-padding); }
.section--alt { background: var(--color-bg-alt); }
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.section-header { text-align: left; margin-bottom: 40px; }
.section-header h2 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.08;
  color: var(--color-text);
}
.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 6px;
  font-weight: 400;
}
.section-header--center { text-align: center; }

/* ─── Hero (Store) ─── */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg);
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
}
.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}
.store-hero .hero-links {
  margin-top: 20px;
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
}
.store-hero .hero-links a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ─── Product Icon Bar ─── */
.icon-bar {
  padding: 24px 0;
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.icon-bar__inner {
  display: flex;
  gap: 32px;
  justify-content: center;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  min-width: max-content;
}
.icon-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-text);
  font-size: 12px;
  font-weight: 400;
  white-space: nowrap;
  transition: opacity var(--transition);
}
.icon-bar__item:hover { opacity: 0.7; text-decoration: none; }
.icon-bar__icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

/* ─── Carousel ─── */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track-container { overflow: hidden; position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
  padding: 4px 0;
}
.carousel-track > * { flex-shrink: 0; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  color: var(--color-text);
  font-size: 18px;
}
.carousel-arrow:hover { background: #fff; box-shadow: 0 4px 14px rgba(0,0,0,0.16); }
.carousel-arrow--prev { left: -8px; }
.carousel-arrow--next { right: -8px; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }

/* ─── Product Cards ─── */
.product-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px 28px;
  width: 320px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }

.product-card__badge {
  position: absolute;
  top: 16px;
  left: 20px;
  background: #e84c3d;
  color: white;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.product-card__image {
  width: 200px;
  height: 180px;
  object-fit: contain;
  margin-bottom: 20px;
  border-radius: 12px;
  background: linear-gradient(135deg, #e8e8ed 0%, #f5f5f7 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.product-card__image img { width: 100%; height: 100%; object-fit: contain; }
.product-card__name {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 4px;
  letter-spacing: -0.01em;
}
.product-card__tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 12px;
  line-height: 1.4;
}
.product-card__price {
  font-size: 17px;
  font-weight: 500;
  margin-bottom: 2px;
}
.product-card__monthly {
  font-size: 14px;
  color: var(--color-text-secondary);
}

/* ─── Homepage Hero Tiles ─── */
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 0 24px;
  max-width: calc(var(--max-width) + 48px);
  margin: 0 auto;
}
.hero-tile {
  border-radius: var(--card-radius);
  padding: 48px 40px 40px;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}
.hero-tile:hover { transform: scale(0.995); }
.hero-tile--dark { color: #fff; }
.hero-tile--dark h3, .hero-tile--dark p { color: #fff; }
.hero-tile--dark .hero-tile__ctas a { color: rgba(255,255,255,0.9); }
.hero-tile--dark .hero-tile__ctas a.cta-buy { color: rgba(255,255,255,0.9); }

.hero-tile h3 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.1;
}
.hero-tile p {
  font-size: 19px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}
.hero-tile__ctas {
  display: flex;
  gap: 24px;
  margin-top: 14px;
}
.hero-tile__ctas a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-weight: 400;
}
.hero-tile__ctas a.cta-buy { color: var(--color-link); }
.hero-tile__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 24px;
  width: 100%;
}
.hero-tile__visual-placeholder {
  width: 280px;
  height: 280px;
  border-radius: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  opacity: 0.3;
}

.hero-tile--phone { background: #1d1d1f; }
.hero-tile--laptop-neo { background: linear-gradient(180deg, #e8f4f8 0%, #d4eaf0 100%); }
.hero-tile--tablet { background: linear-gradient(180deg, #f5f0eb 0%, #e8ddd4 100%); }
.hero-tile--laptop-pro { background: #1d1d1f; }
.hero-tile--earbuds { background: linear-gradient(180deg, #faf5f0 0%, #f0e8de 100%); }
.hero-tile--trade-in { background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); }

/* ─── Entertainment Tabs ─── */
.ent-tabs { display: flex; gap: 0; justify-content: center; margin-bottom: 36px; }
.ent-tab {
  padding: 10px 28px;
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
  background: none;
}
.ent-tab:hover { color: var(--color-text); }
.ent-tab.active { color: var(--color-text); border-bottom-color: var(--color-text); }

.ent-panel { display: none; }
.ent-panel.active { display: block; animation: fadeUp 0.35s ease-out; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.ent-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.ent-card {
  background: var(--color-bg-alt);
  border-radius: 14px;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}
.ent-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.ent-card__visual {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.ent-card__body { padding: 16px 20px 20px; }
.ent-card__title { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.ent-card__desc { font-size: 14px; color: var(--color-text-secondary); margin-bottom: 12px; line-height: 1.4; }
.ent-card__cta { font-size: 14px; font-weight: 500; }

/* ─── Info Cards (Help, Store Diff, etc.) ─── */
.info-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px;
  width: 260px;
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
}
.info-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.info-card__icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: #e8e8ed;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 22px;
}
.info-card__title { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.info-card__desc { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* ─── Brand Collab ─── */
.collab-banner {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: var(--card-radius);
  padding: 60px 48px;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 48px;
}
.collab-banner__content { flex: 1; }
.collab-banner__content h3 { font-size: 36px; font-weight: 700; margin-bottom: 8px; }
.collab-banner__content p { font-size: 17px; opacity: 0.8; line-height: 1.5; }
.collab-banner__visual {
  width: 300px; height: 200px;
  border-radius: 16px;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  flex-shrink: 0;
}

/* ─── Quick Links ─── */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}
.quick-link {
  padding: 10px 20px;
  border: 1px solid var(--color-border);
  border-radius: 980px;
  font-size: 14px;
  color: var(--color-link);
  transition: all var(--transition);
  white-space: nowrap;
}
.quick-link:hover { background: var(--color-bg-alt); text-decoration: none; }

/* ─── Category Page Section Nav ─── */
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.section-nav__inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  min-width: max-content;
}
.section-nav__link {
  padding: 14px 20px;
  font-size: 14px;
  color: var(--color-text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}
.section-nav__link:hover { color: var(--color-text); text-decoration: none; }
.section-nav__link.active { color: var(--color-text); border-bottom-color: var(--color-text); }

/* ─── Category Hero ─── */
.category-hero {
  text-align: center;
  padding: 60px 24px 40px;
}
.category-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.005em;
}
.category-hero p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}

/* ─── Savings / Special Store Cards ─── */
.save-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px;
  width: 280px;
  transition: transform var(--transition), box-shadow var(--transition);
}
.save-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.save-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: #e8e8ed;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  font-size: 20px;
}
.save-card__title { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.save-card__desc { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* ─── Footer ─── */
.site-footer {
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: 40px 24px 24px;
  font-size: 13px;
  color: var(--color-text-secondary);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 24px 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 10px;
  cursor: default;
}
.footer-col ul { display: flex; flex-direction: column; gap: 6px; }
.footer-col a {
  font-size: 12px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--color-text); text-decoration: none; }

.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 16px;
  font-size: 12px;
  line-height: 1.6;
}
.footer-legal p { margin-bottom: 8px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 12px;
  font-size: 12px;
}

/* ─── Audio promo banner ─── */
.audio-promo {
  background: linear-gradient(135deg, #ff6b6b 0%, #ee5a24 100%);
  color: #fff;
  border-radius: 12px;
  padding: 16px 24px;
  margin-bottom: 24px;
  font-size: 15px;
  font-weight: 500;
  text-align: center;
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr 1fr; }
  .ent-grid { grid-template-columns: repeat(2, 1fr); }
  .section-header h2 { font-size: 36px; }
  .store-hero h1 { font-size: 44px; }
  .hero-tile h3 { font-size: 32px; }
  .hero-tile { min-height: 400px; padding: 36px 28px 28px; }
  .collab-banner { flex-direction: column; text-align: center; padding: 40px 28px; }
  .collab-banner__visual { width: 100%; max-width: 300px; }
}

@media (max-width: 768px) {
  .top-nav__links { display: none; }
  .nav-hamburger { display: flex; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-tile { min-height: 360px; }
  .hero-tile h3 { font-size: 28px; }
  .ent-grid { grid-template-columns: 1fr 1fr; }
  .section-header h2 { font-size: 28px; }
  .section-header p { font-size: 17px; }
  .store-hero h1 { font-size: 36px; }
  .category-hero h1 { font-size: 36px; }
  .section { padding: 48px 0; }
  .product-card { width: 260px; padding: 24px 20px 20px; }
  .info-card { width: 220px; }
  .save-card { width: 240px; }

  .footer-columns { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--color-border); }
  .footer-col h4 {
    cursor: pointer;
    padding: 14px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-col h4::after { content: '+'; font-size: 18px; font-weight: 300; transition: transform var(--transition); }
  .footer-col.is-open h4::after { transform: rotate(45deg); }
  .footer-col ul { display: none; padding-bottom: 14px; }
  .footer-col.is-open ul { display: flex; }
}

@media (max-width: 480px) {
  .ent-grid { grid-template-columns: 1fr; }
  .ent-tabs { flex-wrap: wrap; gap: 0; }
  .ent-tab { padding: 8px 16px; font-size: 14px; }
  .hero-tile__visual-placeholder { width: 180px; height: 180px; }
}

/* Orchard — Premium Tech Store */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root {
  --color-bg: #ffffff;
  --color-bg-alt: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --section-padding: 80px 0;
  --card-radius: 18px;
  --transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body { font-family: var(--font-stack); color: var(--color-text); background: var(--color-bg); line-height: 1.47059; font-size: 17px; overflow-x: hidden; }
a { color: var(--color-link); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-link-hover); text-decoration: underline; }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ─── Ribbon Banner ─── */
.ribbon {
  background: var(--color-bg-alt);
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
}
.ribbon a { font-weight: 500; }

/* ─── Top Navigation ─── */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
}
.top-nav__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 48px;
}
.top-nav__logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
}
.top-nav__logo:hover { text-decoration: none; color: var(--color-text); }
.top-nav__links { display: flex; gap: 28px; align-items: center; }
.top-nav__links a {
  font-size: 14px;
  color: var(--color-text);
  font-weight: 400;
  opacity: 0.8;
  transition: opacity var(--transition);
}
.top-nav__links a:hover { opacity: 1; text-decoration: none; }
.top-nav__links a.active { opacity: 1; font-weight: 600; }

.nav-hamburger { display: none; width: 36px; height: 36px; align-items: center; justify-content: center; }
.nav-hamburger svg { width: 20px; height: 20px; }

/* ─── Mobile Nav ─── */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 999;
}
.mobile-nav-overlay.is-open { display: block; }
.mobile-nav {
  position: fixed;
  top: 0; right: -280px;
  width: 280px; height: 100%;
  background: #fff;
  z-index: 1001;
  padding: 60px 24px 24px;
  transition: right var(--transition);
  box-shadow: -4px 0 20px rgba(0,0,0,0.1);
}
.mobile-nav.is-open { right: 0; }
.mobile-nav a { display: block; padding: 14px 0; font-size: 17px; color: var(--color-text); border-bottom: 1px solid var(--color-border); }
.mobile-nav__close {
  position: absolute; top: 16px; right: 16px;
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; color: var(--color-text-secondary);
}

/* ─── Section Containers ─── */
.section { padding: var(--section-padding); }
.section--alt { background: var(--color-bg-alt); }
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.section-header { text-align: left; margin-bottom: 40px; }
.section-header h2 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.08;
  color: var(--color-text);
}
.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 6px;
  font-weight: 400;
}
.section-header--center { text-align: center; }

/* ─── Hero (Store) ─── */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg);
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
}
.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}
.store-hero .hero-links {
  margin-top: 20px;
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
}
.store-hero .hero-links a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ─── Product Icon Bar ─── */
.icon-bar {
  padding: 24px 0;
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.icon-bar__inner {
  display: flex;
  gap: 32px;
  justify-content: center;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  min-width: max-content;
}
.icon-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-text);
  font-size: 12px;
  font-weight: 400;
  white-space: nowrap;
  transition: opacity var(--transition);
}
.icon-bar__item:hover { opacity: 0.7; text-decoration: none; }
.icon-bar__icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

/* ─── Carousel ─── */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track-container { overflow: hidden; position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
  padding: 4px 0;
}
.carousel-track > * { flex-shrink: 0; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  color: var(--color-text);
  font-size: 18px;
}
.carousel-arrow:hover { background: #fff; box-shadow: 0 4px 14px rgba(0,0,0,0.16); }
.carousel-arrow--prev { left: -8px; }
.carousel-arrow--next { right: -8px; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }

/* ─── Product Cards ─── */
.product-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px 28px;
  width: 320px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }

.product-card__badge {
  position: absolute;
  top: 16px;
  left: 20px;
  background: #e84c3d;
  color: white;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.product-card__image {
  width: 200px;
  height: 180px;
  object-fit: contain;
  margin-bottom: 20px;
  border-radius: 12px;
  background: linear-gradient(135deg, #e8e8ed 0%, #f5f5f7 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.product-card__image img { width: 100%; height: 100%; object-fit: contain; }
.product-card__name {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 4px;
  letter-spacing: -0.01em;
}
.product-card__tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 12px;
  line-height: 1.4;
}
.product-card__price {
  font-size: 17px;
  font-weight: 500;
  margin-bottom: 2px;
}
.product-card__monthly {
  font-size: 14px;
  color: var(--color-text-secondary);
}

/* ─── Homepage Hero Tiles ─── */
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 0 24px;
  max-width: calc(var(--max-width) + 48px);
  margin: 0 auto;
}
.hero-tile {
  border-radius: var(--card-radius);
  padding: 48px 40px 40px;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}
.hero-tile:hover { transform: scale(0.995); }
.hero-tile--dark { color: #fff; }
.hero-tile--dark h3, .hero-tile--dark p { color: #fff; }
.hero-tile--dark .hero-tile__ctas a { color: rgba(255,255,255,0.9); }
.hero-tile--dark .hero-tile__ctas a.cta-buy { color: rgba(255,255,255,0.9); }

.hero-tile h3 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.1;
}
.hero-tile p {
  font-size: 19px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}
.hero-tile__ctas {
  display: flex;
  gap: 24px;
  margin-top: 14px;
}
.hero-tile__ctas a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-weight: 400;
}
.hero-tile__ctas a.cta-buy { color: var(--color-link); }
.hero-tile__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 24px;
  width: 100%;
}
.hero-tile__visual-placeholder {
  width: 280px;
  height: 280px;
  border-radius: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  opacity: 0.3;
}

.hero-tile--phone { background: #1d1d1f; }
.hero-tile--laptop-neo { background: linear-gradient(180deg, #e8f4f8 0%, #d4eaf0 100%); }
.hero-tile--tablet { background: linear-gradient(180deg, #f5f0eb 0%, #e8ddd4 100%); }
.hero-tile--laptop-pro { background: #1d1d1f; }
.hero-tile--earbuds { background: linear-gradient(180deg, #faf5f0 0%, #f0e8de 100%); }
.hero-tile--trade-in { background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); }

/* ─── Entertainment Tabs ─── */
.ent-tabs { display: flex; gap: 0; justify-content: center; margin-bottom: 36px; }
.ent-tab {
  padding: 10px 28px;
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
  background: none;
}
.ent-tab:hover { color: var(--color-text); }
.ent-tab.active { color: var(--color-text); border-bottom-color: var(--color-text); }

.ent-panel { display: none; }
.ent-panel.active { display: block; animation: fadeUp 0.35s ease-out; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.ent-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.ent-card {
  background: var(--color-bg-alt);
  border-radius: 14px;
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
}
.ent-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.ent-card__visual {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.ent-card__body { padding: 16px 20px 20px; }
.ent-card__title { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.ent-card__desc { font-size: 14px; color: var(--color-text-secondary); margin-bottom: 12px; line-height: 1.4; }
.ent-card__cta { font-size: 14px; font-weight: 500; }

/* ─── Info Cards (Help, Store Diff, etc.) ─── */
.info-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px;
  width: 260px;
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
}
.info-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.info-card__icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: #e8e8ed;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 22px;
}
.info-card__title { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.info-card__desc { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* ─── Brand Collab ─── */
.collab-banner {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  border-radius: var(--card-radius);
  padding: 60px 48px;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 48px;
}
.collab-banner__content { flex: 1; }
.collab-banner__content h3 { font-size: 36px; font-weight: 700; margin-bottom: 8px; }
.collab-banner__content p { font-size: 17px; opacity: 0.8; line-height: 1.5; }
.collab-banner__visual {
  width: 300px; height: 200px;
  border-radius: 16px;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  flex-shrink: 0;
}

/* ─── Quick Links ─── */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}
.quick-link {
  padding: 10px 20px;
  border: 1px solid var(--color-border);
  border-radius: 980px;
  font-size: 14px;
  color: var(--color-link);
  transition: all var(--transition);
  white-space: nowrap;
}
.quick-link:hover { background: var(--color-bg-alt); text-decoration: none; }

/* ─── Category Page Section Nav ─── */
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.section-nav__inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  min-width: max-content;
}
.section-nav__link {
  padding: 14px 20px;
  font-size: 14px;
  color: var(--color-text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}
.section-nav__link:hover { color: var(--color-text); text-decoration: none; }
.section-nav__link.active { color: var(--color-text); border-bottom-color: var(--color-text); }

/* ─── Category Hero ─── */
.category-hero {
  text-align: center;
  padding: 60px 24px 40px;
}
.category-hero h1 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.005em;
}
.category-hero p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}

/* ─── Savings / Special Store Cards ─── */
.save-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px;
  width: 280px;
  transition: transform var(--transition), box-shadow var(--transition);
}
.save-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.save-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: #e8e8ed;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  font-size: 20px;
}
.save-card__title { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.save-card__desc { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* ─── Footer ─── */
.site-footer {
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: 40px 24px 24px;
  font-size: 13px;
  color: var(--color-text-secondary);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 24px 32px;
  margin-bottom: 32px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 10px;
  cursor: default;
}
.footer-col ul { display: flex; flex-direction: column; gap: 6px; }
.footer-col a {
  font-size: 12px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--color-text); text-decoration: none; }

.footer-legal {
  border-top: 1px solid var(--color-border);
  padding-top: 16px;
  font-size: 12px;
  line-height: 1.6;
}
.footer-legal p { margin-bottom: 8px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 12px;
  font-size: 12px;
}

/* ─── Audio promo banner ─── */
.audio-promo {
  background: linear-gradient(135deg, #ff6b6b 0%, #ee5a24 100%);
  color: #fff;
  border-radius: 12px;
  padding: 16px 24px;
  margin-bottom: 24px;
  font-size: 15px;
  font-weight: 500;
  text-align: center;
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr 1fr; }
  .ent-grid { grid-template-columns: repeat(2, 1fr); }
  .section-header h2 { font-size: 36px; }
  .store-hero h1 { font-size: 44px; }
  .hero-tile h3 { font-size: 32px; }
  .hero-tile { min-height: 400px; padding: 36px 28px 28px; }
  .collab-banner { flex-direction: column; text-align: center; padding: 40px 28px; }
  .collab-banner__visual { width: 100%; max-width: 300px; }
}

@media (max-width: 768px) {
  .top-nav__links { display: none; }
  .nav-hamburger { display: flex; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-tile { min-height: 360px; }
  .hero-tile h3 { font-size: 28px; }
  .ent-grid { grid-template-columns: 1fr 1fr; }
  .section-header h2 { font-size: 28px; }
  .section-header p { font-size: 17px; }
  .store-hero h1 { font-size: 36px; }
  .category-hero h1 { font-size: 36px; }
  .section { padding: 48px 0; }
  .product-card { width: 260px; padding: 24px 20px 20px; }
  .info-card { width: 220px; }
  .save-card { width: 240px; }

  .footer-columns { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--color-border); }
  .footer-col h4 {
    cursor: pointer;
    padding: 14px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-col h4::after { content: '+'; font-size: 18px; font-weight: 300; transition: transform var(--transition); }
  .footer-col.is-open h4::after { transform: rotate(45deg); }
  .footer-col ul { display: none; padding-bottom: 14px; }
  .footer-col.is-open ul { display: flex; }
}

@media (max-width: 480px) {
  .ent-grid { grid-template-columns: 1fr; }
  .ent-tabs { flex-wrap: wrap; gap: 0; }
  .ent-tab { padding: 8px 16px; font-size: 14px; }
  .hero-tile__visual-placeholder { width: 180px; height: 180px; }
}

raw_arguments.content:
/* Orchard — Premium Tech Store */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root {
  --color-bg: #ffffff;
  --color-bg-alt: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --section-padding: 80px 0;
  --card-radius: 18px;
  --transition: 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body { font-family: var(--font-stack); color: var(--color-text); background: var(--color-bg); line-height: 1.47059; font-size: 17px; overflow-x: hidden; }
a { color: var(--color-link); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-link-hover); text-decoration: underline; }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ─── Ribbon Banner ─── */
.ribbon {
  background: var(--color-bg-alt);
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border);
}
.ribbon a { font-weight: 500; }

/* ─── Top Navigation ─── */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 24px;
}
.top-nav__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 48px;
}
.top-nav__logo {
  font-size: 21px;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
}
.top-nav__logo:hover { text-decoration: none; color: var(--color-text); }
.top-nav__links { display: flex; gap: 28px; align-items: center; }
.top-nav__links a {
  font-size: 14px;
  color: var(--color-text);
  font-weight: 400;
  opacity: 0.8;
  transition: opacity var(--transition);
}
.top-nav__links a:hover { opacity: 1; text-decoration: none; }
.top-nav__links a.active { opacity: 1; font-weight: 600; }

.nav-hamburger { display: none; width: 36px; height: 36px; align-items: center; justify-content: center; }
.nav-hamburger svg { width: 20px; height: 20px; }

/* ─── Mobile Nav ─── */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 999;
}
.mobile-nav-overlay.is-open { display: block; }
.mobile-nav {
  position: fixed;
  top: 0; right: -280px;
  width: 280px; height: 100%;
  background: #fff;
  z-index: 1001;
  padding: 60px 24px 24px;
  transition: right var(--transition);
  box-shadow: -4px 0 20px rgba(0,0,0,0.1);
}
.mobile-nav.is-open { right: 0; }
.mobile-nav a { display: block; padding: 14px 0; font-size: 17px; color: var(--color-text); border-bottom: 1px solid var(--color-border); }
.mobile-nav__close {
  position: absolute; top: 16px; right: 16px;
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; color: var(--color-text-secondary);
}

/* ─── Section Containers ─── */
.section { padding: var(--section-padding); }
.section--alt { background: var(--color-bg-alt); }
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.section-header { text-align: left; margin-bottom: 40px; }
.section-header h2 {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.003em;
  line-height: 1.08;
  color: var(--color-text);
}
.section-header p {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-top: 6px;
  font-weight: 400;
}
.section-header--center { text-align: center; }

/* ─── Hero (Store) ─── */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg);
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.05;
}
.store-hero .subtitle {
  font-size: 24px;
  color: var(--color-text-secondary);
  margin-top: 8px;
  font-weight: 400;
}
.store-hero .hero-links {
  margin-top: 20px;
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
}
.store-hero .hero-links a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* ─── Product Icon Bar ─── */
.icon-bar {
  padding: 24px 0;
  border-bottom: 1px solid var(--color-border);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.icon-bar__inner {
  display: flex;
  gap: 32px;
  justify-content: center;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  min-width: max-content;
}
.icon-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-text);
  font-size: 12px;
  font-weight: 400;
  white-space: nowrap;
  transition: opacity var(--transition);
}
.icon-bar__item:hover { opacity: 0.7; text-decoration: none; }
.icon-bar__icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

/* ─── Carousel ─── */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track-container { overflow: hidden; position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
  padding: 4px 0;
}
.carousel-track > * { flex-shrink: 0; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  color: var(--color-text);
  font-size: 18px;
}
.carousel-arrow:hover { background: #fff; box-shadow: 0 4px 14px rgba(0,0,0,0.16); }
.carousel-arrow--prev { left: -8px; }
.carousel-arrow--next { right: -8px; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }

/* ─── Product Cards ─── */
.product-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px 28px;
  width: 320px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}
.product-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }

.product-card__badge {
  position: absolute;
  top: 16px;
  left: 20px;
  background: #e84c3d;
  color: white;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.product-card__image {
  width: 200px;
  height: 180px;
  object-fit: contain;
  margin-bottom: 20px;
  border-radius: 12px;
  background: linear-gradient(135deg, #e8e8ed 0%, #f5f5f7 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.product-card__image img { width: 100%; height: 100%; object-fit: contain; }
.product-card__name {
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 4px;
  letter-spacing: -0.01em;
}
.product-card__tagline {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 12px;
  line-height: 1.4;
}
.product-card__price {
  font-size: 17px;
  font-weight: 500;
  margin-bottom: 2px;
}
.product-card__monthly {
  font-size: 14px;
  color: var(--color-text-secondary);
}

/* ─── Homepage Hero Tiles ─── */
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 0 24px;
  max-width: calc(var(--max-width) + 48px);
  margin: 0 auto;
}
.hero-tile {
  border-radius: var(--card-radius);
  padding: 48px 40px 40px;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: transform var(--transition);
}
.hero-tile:hover { transform: scale(0.995); }
.hero-tile--dark { color: #fff; }
.hero-tile--dark h3, .hero-tile--dark p { color: #fff; }
.hero-tile--dark .hero-tile__ctas a { color: rgba(255,255,255,0.9); }
.hero-tile--dark .hero-tile__ctas a.cta-buy { color: rgba(255,255,255,0.9); }

.hero-tile h3 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.1;
}
.hero-tile p {
  font-size: 19px;
  color: var(--color-text-secondary);
  margin-top: 6px;
}
.hero-tile__ctas {
  display: flex;
  gap: 24px;
  margin-top: 14px;
}
.hero-tile__ctas a {
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-weight: 400;
}
.hero-tile__ctas a.cta-buy { color: var(--color-link); }
.hero-tile__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 24px;
  width: 100%;
}
.hero-tile__visual-placeholder {
  width: 280px;
  height: 280px;
  border-radius: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  opacity: 0.3;
}

.hero-tile--phone { background: #1d1d1f; }
.hero-tile--laptop-neo { background: linear-gradient(180deg, #e8f4f8 0%, #d4eaf0 100%); }
.hero-tile--tablet { background: linear-gradient(180deg, #f5f0eb 0%, #e8ddd4 100%); }
.hero-tile--laptop-pro { background: #1d1d1f; }
.hero-tile--earbuds { background: linear-gradient(180deg, #faf5f0 0%, #f0e8de 100%); }
.hero-tile--trade-in { background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); }

